"""users-api: Flask service that owns user data (port assigned at runtime)."""

import sys
import time

from flask import Flask, jsonify, request

app = Flask(__name__)

# Seed data: the "database" of users owned by this service.
USERS = {
    "1": {"id": "1", "name": "Alice", "email": "alice@example.com"},
    "2": {"id": "2", "name": "Bob", "email": "bob@example.com"},
}


@app.get("/health")
def health():
    return jsonify({"status": "ok"})


@app.get("/users/<user_id>")
def get_user(user_id: str):
    # Test hook: ?delay=<ms> makes this endpoint respond slowly so callers
    # can exercise their timeout/fallback behavior.
    delay_ms = request.args.get("delay", type=int)
    if delay_ms:
        time.sleep(delay_ms / 1000.0)

    user = USERS.get(user_id)
    if user is None:
        return jsonify({"error": "user not found"}), 404
    return jsonify(user)


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=int(sys.argv[1]) if len(sys.argv) > 1 else 5001)

